/**
 * dev.mjs — Start the workspace host (local, no npx).
 * Auto-generated by `npx @flowot/nx-pn init <name>`.
 *
 * Usage: node scripts/dev.mjs
 *
 * This script:
 *   1. Resolves the local nx-pn binary from node_modules
 *   2. Probes :4560; if down, spawns a detached host process
 *   3. Waits up to 30s for the host to become ready
 */

import { readFile } from 'node:fs/promises'
import { spawn } from 'node:child_process'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const __root = dirname(fileURLToPath(import.meta.url))
const localBase = join(__root, 'node_modules', '@flowot', 'nx-pn', 'bin', 'nx-pn.mjs')

const PORT = 4560
const HOST = `http://localhost:${PORT}`
const MAX_WAIT_MS = 30_000

async function probe(port) {
  try {
    const res = await fetch(`http://localhost:${port}/api/plugins`, { signal: AbortSignal.timeout(2000) })
    return res.ok
  } catch {
    return false
  }
}

async function waitForHost(maxMs) {
  const interval = 500
  const deadline = Date.now() + maxMs
  while (Date.now() < deadline) {
    if (await probe(PORT)) return true
    await new Promise((r) => setTimeout(r, interval))
  }
  return false
}

console.log('[dev] probing ' + HOST + ' ...')
const alreadyUp = await probe(PORT)
if (alreadyUp) {
  console.log('[dev] host already running at ' + HOST)
} else {
  console.log('[dev] no host detected — spawning local nx-pn ...')
  const child = spawn('node', [localBase, '--no-open', '--port', String(PORT)], {
    detached: true,
    stdio: 'ignore',
    windowsHide: true,
  })
  child.unref()
  console.log('[dev] spawned pid ' + child.pid + ' (detached)')

  const ready = await waitForHost(MAX_WAIT_MS)
  if (!ready) {
    console.error('[dev] FATAL: host did not become ready within ' + (MAX_WAIT_MS / 1000) + 's')
    process.exit(1)
  }
  console.log('[dev] host ready at ' + HOST)
}

console.log('[dev] done — connect to ' + HOST + ' in your browser')
